<?php $v = static fn(string $k, $d = '') => old($k, $s[$k] ?? $d); $err = static fn(string $k) => field_error($k) ? ' has-error' : ''; ?>
<div class="page-head"><div><h1><?= e(t('admin.settings')) ?></h1></div></div>
<form method="post" class="card" style="max-width:720px" action="<?= e(url('admin/settings')) ?>" novalidate><?= csrf_field() ?>
<div class="form-grid">
  <div class="field<?= $err('org_name_en') ?>"><label for="org_name_en"><?= e(t('settings.org_name_en')) ?> *</label><input type="text" id="org_name_en" name="org_name_en" value="<?= e($v('org_name_en')) ?>"><?= field_error('org_name_en') ?></div>
  <div class="field<?= $err('org_name_ar') ?>"><label for="org_name_ar"><?= e(t('settings.org_name_ar')) ?> *</label><input type="text" dir="rtl" id="org_name_ar" name="org_name_ar" value="<?= e($v('org_name_ar')) ?>"><?= field_error('org_name_ar') ?></div>
