  <div class="field<?= $err('currency_decimals') ?>"><label for="currency_decimals"><?= e(t('settings.currency_decimals')) ?></label><select id="currency_decimals" name="currency_decimals"><?php foreach (['0', '1', '2', '3'] as $d): ?><option value="<?= $d ?>"<?= sel($v('currency_decimals', '3'), $d) ?>><?= $d ?></option><?php endforeach; ?></select><p class="hint"><?= e(t('settings.decimals_hint')) ?></p></div>
  <div class="field<?= $err('currency_symbol_en') ?>"><label for="currency_symbol_en"><?= e(t('settings.symbol_en')) ?></label><input type="text" id="currency_symbol_en" name="currency_symbol_en" value="<?= e($v('currency_symbol_en')) ?>"><?= field_error('currency_symbol_en') ?></div>
  <div class="field<?= $err('currency_symbol_ar') ?>"><label for="currency_symbol_ar"><?= e(t('settings.symbol_ar')) ?></label><input type="text" dir="rtl" id="currency_symbol_ar" name="currency_symbol_ar" value="<?= e($v('currency_symbol_ar')) ?>"><?= field_error('currency_symbol_ar') ?></div>
  <div class="field"><label for="default_lang"><?= e(t('settings.default_lang')) ?></label><select id="default_lang" name="default_lang"><option value="ar"<?= sel($v('default_lang', 'ar'), 'ar') ?>>العربية</option><option value="en"<?= sel($v('default_lang', 'ar'), 'en') ?>>English</option></select></div>
  <div class="field<?= $err('review_warning_days') ?>"><label for="review_warning_days"><?= e(t('settings.review_warning_days')) ?></label><input type="number" id="review_warning_days" name="review_warning_days" min="0" max="365" value="<?= e($v('review_warning_days', '30')) ?>"><?= field_error('review_warning_days') ?></div>
  <div class="field<?= $err('accept_level2_min') ?>"><label for="accept_level2_min"><?= e(t('settings.accept_level2')) ?></label><input type="number" id="accept_level2_min" name="accept_level2_min" min="1" max="25" value="<?= e($v('accept_level2_min', '20')) ?>"><p class="hint"><?= e(t('settings.accept_level2_hint')) ?></p><?= field_error('accept_level2_min') ?></div>
  <div class="field<?= $err('incident_escalation_threshold') ?>"><label for="incident_escalation_threshold"><?= e(t('settings.incident_threshold')) ?></label><input type="text" id="incident_escalation_threshold" name="incident_escalation_threshold" inputmode="decimal" value="<?= e($v('incident_escalation_threshold')) ?>"><p class="hint"><?= e(t('settings.incident_threshold_hint')) ?></p><?= field_error('incident_escalation_threshold') ?></div>
